    id character varying(36) NOT NULL,
    reference character varying(32) NOT NULL,
    client_id character varying(36),
    fiat_deposit_id character varying(36),
    otc_quote_id character varying(36),
    outbound_transfer_id character varying(36),
    recipient_wallet character varying(256) NOT NULL,
    recipient_network character varying(16) NOT NULL,
    amount_eur numeric(30,6) NOT NULL,
    amount_usdt numeric(30,6),
    status character varying(24) NOT NULL,
    sender_name character varying(256),
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.transfer_requests OWNER TO alshumookh_db_user;

--
-- Name: treasury_wallets; Type: TABLE; Schema: public; Owner: alshumookh_db_user
